from solution import compare_versions

def test_equal_with_trailing_zeros():
    assert compare_versions('1.0', '1.0.0') == 0

def test_numeric_not_lexical():
    assert compare_versions('1.10', '1.9') == 1

def test_basic_ordering():
    assert compare_versions('2.0.1', '2.0.1') == 0
    assert compare_versions('0.9.9', '1.0.0') == -1
    assert compare_versions('1.2.3', '1.2.0') == 1
